async page=>{
 const out={};
 await page.evaluate(()=>{CloudTaskWorkspace.clearActiveContext();RouteRuntime.openPrimary('predictive-tasks');CloudTaskWorkspace.start('预外呼');});await page.waitForSelector('#wizardName');
 out.shortCnoSubmit=await page.evaluate(()=>{const a=CloudCallData.agents.find(a=>a.contactCenterIdentityId==='CCI-N-001'),old=a.cno;a.cno='12';try{CloudTaskWorkspace.setTenant('TEN-NISSAN-HQ');CloudTaskWorkspace.update('name','审计-已有12号坐席');CloudTaskWorkspace.setResource('skillGroupId','SG-ALI-HQ-SALES');CloudTaskWorkspace.setResource('callerNumberId','NUM-400-8801');CloudTaskWorkspace.update('minAvailableAgentCount','1');const c=CustomerTasks.pendingForTask('TEN-NISSAN-HQ','7522240')[0];if(c)CloudTaskWorkspace.toggleCustomer(c.id,true);CloudTaskWorkspace.next();CloudTaskWorkspace.next();CloudTaskWorkspace.next();CloudTaskWorkspace.submit();const t=CloudCallData.tasks.find(t=>t.name==='审计-已有12号坐席');return t?{created:true,status:t.status,request:t.alictiCreateDraft,response:t.alictiCreateResponse}: {created:false,message:document.body.innerText.slice(-1200)};}finally{a.cno=old;}});
 await page.evaluate(()=>{CloudTaskWorkspace.clearActiveContext();RouteRuntime.openPrimary('predictive-tasks');CloudTaskWorkspace.start('预外呼');});await page.waitForSelector('#wizardName');
 out.template=await page.evaluate(()=>{CloudTaskWorkspace.setTenant('TEN-NISSAN-HQ');CloudTaskWorkspace.update('name','审计-模板含重呼');CloudTaskWorkspace.setResource('skillGroupId','SHOWCASE-HQ-SKILL-SALES');CloudTaskWorkspace.setResource('callerNumberId','SHOWCASE-HQ-NUM');CloudTaskWorkspace.update('minAvailableAgentCount','1');CloudTaskWorkspace.setRetryMode('advanced');CloudTaskWorkspace.toggleRetryCode(710,true);CloudTaskWorkspace.changeRetryCount('2');CloudTaskWorkspace.changeRetryInterval('uniform','15','minutes');CloudTaskWorkspace.setResource('saveAsTemplate',true);CloudTaskWorkspace.next();CloudTaskWorkspace.next();CloudTaskWorkspace.next();CloudTaskWorkspace.submit();const plan=CloudCallData.callPlans.find(p=>p.name==='审计-模板含重呼');if(!plan)return {error:document.body.innerText.slice(-1000)};CloudTaskWorkspace.start('预外呼');CloudTaskWorkspace.setTenant('TEN-NISSAN-HQ');CloudTaskWorkspace.selectPlan(plan.callPlanId);const id=sessionStorage.getItem('cloud-task-wizard-active-v1'),d=JSON.parse(sessionStorage.getItem('cloud-task-wizard-drafts-v1')).find(d=>d.draftId===id);return {template:plan,applied:d.values};});
 out.candidateControl=await page.evaluate(()=>CloudCallData.tasks.filter(t=>t.tenantId==='TEN-NISSAN-HQ').map(t=>({id:t.taskId,name:t.name,status:t.status,type:t.callType,total:t.total,group:t.targetSkillGroupId||t.executionConfig?.targetSkillGroupId,problem:CloudTaskWorkspace.simulationResourceError(t,true)})));
 out.taskReadValidation=await page.evaluate(()=>[{}, {result:0,data:{taskProperty:{id:1,status:99}}},{result:0,data:{taskProperty:{id:2,status:1}}},{result:0,data:{taskProperty:{id:1,status:1,enterpriseId:9}}},{result:0,data:{taskProperty:{id:1,status:1}}}].map(r=>AliCtiAdapter.readTaskControlResult(r,1,'7522240')));
 return out;
}
